package org.jlinalg.cli;

import org.jlinalg.genetics.BioMartQueries;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Native source-bound query planning and unchanged-original typed biomaRt retrieval. */
public final class BiomartWorkflowCli {
    private BiomartWorkflowCli() { }
    static final String ACTION="Require exit0 AND analysis-status.json result_admitted=true. Read WARNINGS.md, original logs, raw HTTP events, native query/coercion ledgers, typed tables and RDS files. SKIP3: dependent annotation was skipped; supply the named exact permitted Windows R4.6.1/biomaRt runtime or explicitly restore the requested endpoint, release and assembly. Where installation is forbidden keep analysis skipped. FAIL2: the whole batch is unadmitted, including earlier successful cases. Preserve inputs, failed attempts and provisional worker files; correct the named query/runtime/service/capacity/timeout cause and retry NEW output paths. Never silently choose another release/build, merge symbols, deduplicate one-to-many rows, replace NA/NaN/Inf, construct a paper mask or infer a nearest-gene rule.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream output,PrintStream error){
        if(args.length==1&&args[0].equals("--help")){emit(output,"java -cp DEVELOPMENT.jar org.jlinalg.cli.BiomartWorkflowCli --request request.json\nNative Java17+ planning; original R retrieval currently requires captured Windows x86_64 R4.6.1 and biomaRt2.60.1/2.68.0.\n"+ACTION);return 0;}
        Path stage=null,destination=null;int exit=2;var warnings=new ArrayList<String>();warnings.add(ACTION);var state=new LinkedHashMap<String,Object>();state.put("status","RUNNING_NO_RESULT_ADMITTED");state.put("result_admitted",false);state.put("required_action",ACTION);state.put("started_at",Instant.now().toString());boolean querying=false;
        try{
            require(args.length==2&&args[0].equals("--request"),"Use --request FILE or --help");Path request=Path.of(args[1]).toAbsolutePath().normalize();var requestPin=NextflowFiles.pin(request,16777216,()->{});byte[] raw=NextflowFiles.bytes(request,16777216);require(requestPin.equals(new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw))),"Request changed during capture");var r=BiomartRequest.parse(object(NextflowParameters.parse(NextflowFiles.utf8(raw),16777216,2000000)),request.getParent());Path out=r.out();require(!Files.exists(out,LinkOption.NOFOLLOW_LINKS),"Output already exists; choose NEW paths");require(canonicalMissing(out).equals(out),"Output parent must be canonical and unlinked");require(!request.startsWith(out)&&!r.runtime().startsWith(out),"Output overlaps original request/runtime manifest");
            if(Files.isRegularFile(r.runtime(),LinkOption.NOFOLLOW_LINKS)){var quick=BiomartRuntime.read(r.runtime(),1048576);for(Object root:object(quick.get("roots")).values()){Path d=canonicalMissing(Path.of(text(root)).toAbsolutePath().normalize());require(!out.startsWith(d)&&!d.startsWith(out),"Output overlaps read-only original runtime; no directories/files created");}}
            Files.createDirectories(out.getParent());stage=Files.createTempDirectory(out.getParent(),".biomart-attempt-");destination=out;Files.write(stage.resolve("request.original.json"),raw,StandardOpenOption.CREATE_NEW);status(stage,state);
            destination=out;emit(error,"biomaRt: checking original dependencies; no result admitted until the complete batch passes.");var runtime=BiomartRuntime.prepare(r);for(Object root:object(runtime.manifest().get("roots")).values()){Path d=Path.of(text(root)).toRealPath();require(!stage.startsWith(d)&&!out.startsWith(d)&&!d.startsWith(out),"Output overlaps read-only original runtime");}NextflowFiles.writeJson(stage.resolve("runtime.original.json"),runtime.manifest());NextflowFiles.writeJson(stage.resolve("effective-request.json"),r.worker());
            Path metadata=Files.createDirectory(stage.resolve("metadata-before"));Map<String,Object> first;
            first=BiomartRuntime.run(metadata,"metadata",r,runtime);
            BiomartHttpAudit.inspect(metadata,first,r,Map.of(),warnings);var binding=BiomartRuntime.read(metadata.resolve("metadata.json"),16777216);var available=new HashSet<>(NextflowFiles.strings(binding.get("attributes")));var filterTypes=new LinkedHashMap<String,String>();for(Object item:list(binding.get("filters"))){var row=object(item);String name=text(row.get("name")),type=text(row.get("type"));String prior=filterTypes.putIfAbsent(name,type);require(prior==null||prior.equals(type),"Ambiguous metadata filter type: "+name);}
            var plans=new LinkedHashMap<String,List<String>>();var planRecords=new ArrayList<Map<String,Object>>();
            for(var query:r.queries()){
                var batches=BioMartQueries.plan(query.request(),available,filterTypes,BioMartQueries.Limits.defaults());plans.put(query.id(),batches.stream().map(BioMartQueries.Batch::xml).toList());
                for(var batch:batches){var coercions=new ArrayList<Map<String,Object>>();for(var c:batch.coercions()){coercions.add(Map.of("filter",c.filter(),"value_index_in_batch",c.valueIndexInBatch(),"original",c.original(),"encoded",c.encoded(),"reason",c.reason()));warnings.add("ORIGINAL INPUT COERCION ["+query.id()+"/batch"+batch.ordinal()+"]: "+c.reason()+"; inspect the complete native-plan.json original/encoded ledger.");}warnings.addAll(batch.sourceWarnings());planRecords.add(Map.of("query",query.id(),"batch",batch.ordinal(),"xml",batch.xml(),"source_warnings",batch.sourceWarnings(),"coercions",coercions));}
            }
            NextflowFiles.writeJson(stage.resolve("native-plan.json"),planRecords);Path worker=Files.createDirectory(stage.resolve("worker"));Files.copy(metadata.resolve("mart.rds"),worker.resolve("mart.rds"));querying=true;emit(error,"biomaRt: running unchanged original getBM with complete HTTP capture.");var report=BiomartRuntime.run(worker,"queries",r,runtime,plans);var audit=BiomartHttpAudit.inspect(worker,report,r,plans,warnings);var reports=list(report.get("cases"));require(reports.size()==r.queries().size(),"Original case family incomplete");
            for(int i=0;i<reports.size();i++){
                var original=object(reports.get(i));String id=r.queries().get(i).id();require(id.equals(text(original.get("id"))),"Original cases reordered");var submitted=new ArrayList<String>();for(Object message:list(original.get("messages"))){String s=text(message);if(s.startsWith("<?xml"))submitted.add(s);}var console=NextflowFiles.strings(original.get("native_console_model"));require(console.equals(submitted)&&console.size()==plans.get(id).size(),"Every original public getBM batch (including temporary-cache hits) must match native XML rendered by original R message");var chunks=NextflowFiles.strings(original.get("original_filter_chunks"));require(chunks.size()==plans.get(id).size(),"Original filter batch family incomplete");for(int k=0;k<chunks.size();k++){require(plans.get(id).get(k).endsWith(chunks.get(k)+"</Dataset></Query>"),"Complete original filter chunk differs from native plan");if(!console.get(k).equals(plans.get(id).get(k)+"\n"))warnings.add("ORIGINAL CONSOLE ENCODING ["+id+"]: original R message renders some Unicode as diagnostic escapes such as <U+03B1>. Native XML and actual HTTP preserve original identifiers; both representations remain in the ledgers.");}for(Object warning:list(original.get("warnings")))warnings.add("ORIGINAL ["+id+"]: "+text(warning));var table=BiomartRuntime.read(worker.resolve(id).resolve("typed-result.json"),Math.toIntExact(Math.min(268435456,r.outputBytes())));long rows=integer(table.get("rows"),0,10000000);require(rows==integer(original.get("rows"),0,10000000)&&list(table.get("row_names")).size()==rows,"Typed original row family incomplete");var columns=list(table.get("columns"));require(columns.size()==list(original.get("columns")).size(),"Typed original column family incomplete");for(int j=0;j<columns.size();j++){var column=object(columns.get(j));require(text(column.get("name")).equals(text(list(original.get("columns")).get(j)))&&list(column.get("values")).size()==rows,"Typed source column/row identities differ");}
            }
            emit(error,"biomaRt: rechecking requested metadata and every runtime file before publishing.");Path after=Files.createDirectory(stage.resolve("metadata-after"));var last=BiomartRuntime.run(after,"metadata",r,runtime);BiomartHttpAudit.inspect(after,last,r,Map.of(),warnings);require(NextflowJson.json(binding).equals(NextflowJson.json(BiomartRuntime.read(after.resolve("metadata.json"),16777216))),"Service metadata changed during the batch; no coherent annotation binding admitted");runtime.verify();require(requestPin.equals(NextflowFiles.pin(request,16777216,()->{})),"Original request changed during analysis");
            warnings.add("Original biomaRt performs table conversion, column matching/reordering and optional HTML fallback. The raw responses, original RDS, row names, classes, typed states and source ordering remain available. No one-to-many rows or unmatched input IDs are silently collapsed or manufactured. A zero-row original response remains zero rows.");warnings.add("Release/assembly labels are verified against the requested service metadata before and after retrieval. These checks cannot independently authenticate the server's biological content or make separate HTTP queries a database transaction. This workflow supplies annotation only; paper-specific enrichment, nearest-gene definitions, filters, historical R images and biological conclusions remain separate.");
            NextflowFiles.writeJson(stage.resolve("provenance.json"),Map.of("edition",r.edition(),"endpoint",r.endpoint(),"HTTP_audit",audit,"namespace_patched",false,"historical_R44_image_reproduced",false,"paper_reproduction",false,"whole_goal_complete",false));Path results=Files.createDirectory(stage.resolve("results"));for(var q:r.queries()){Path dest=Files.createDirectory(results.resolve(q.id()));for(String name:List.of("original-result.rds","original-result.R","original-result.tsv","typed-result.json","original-report.json"))Files.copy(worker.resolve(q.id()).resolve(name),dest.resolve(name));}BiomartRuntime.footprint(stage,r.outputBytes());state.put("status","PASS_ORIGINAL_BIOMART_WORKFLOW");state.put("result_admitted",true);state.put("queries",r.queries().size());exit=0;
            finish(stage,state,warnings);manifest(stage);Files.move(stage,out);stage=null;emit(output,"Original biomaRt batch admitted: "+out);emit(error,"WARNINGS / REQUIRED ACTIONS: "+out.resolve("WARNINGS.md"));return 0;
        }catch(BiomartRuntime.Unavailable unavailable){exit=querying?2:3;state.put("status",exit==3?"SKIP3_DEPENDENCY_OR_EXACT_SERVICE_UNAVAILABLE":"FAIL2_NO_RESULT_ADMITTED");state.put("cause",unavailable.toString());warnings.add(unavailable.toString());}
        catch(Exception failure){state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause",failure.toString());warnings.add(failure.toString());}
        catch(OutOfMemoryError failure){state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("cause","Java heap exhausted; use permitted heap/capacities and NEW output paths without omitting data");warnings.add(state.get("cause").toString());}
        state.put("result_admitted",false);if(stage!=null)try{quarantine(stage);finish(stage,state,warnings);manifest(stage);if(destination!=null&&!Files.exists(destination)){Files.move(stage,destination);stage=destination;}}catch(Exception recording){emit(error,"FAIL2: final diagnostic/publication recording failed; owned attempt retained at "+stage+": "+recording);exit=2;}
        emit(error,(exit==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 NO RESULT ADMITTED: ")+state.get("cause")+"\nRetained attempt: "+stage+"\nWARNINGS / REQUIRED ACTION: "+ACTION);return exit;
    }
    private static void quarantine(Path stage)throws IOException{if(Files.exists(stage.resolve("results")))Files.move(stage.resolve("results"),stage.resolve("unadmitted-partial-results"));}
    private static Path canonicalMissing(Path path)throws IOException{var suffix=new ArrayDeque<Path>();Path p=path;while(!Files.exists(p,LinkOption.NOFOLLOW_LINKS)){require(p.getParent()!=null,"Missing canonical output ancestor");suffix.addFirst(p.getFileName());p=p.getParent();}p=p.toRealPath();for(Path part:suffix)p=p.resolve(part);return p;}
    private static void status(Path stage,Map<String,Object> state)throws IOException{Files.writeString(stage.resolve("analysis-status.json"),NextflowJson.json(state)+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
    private static void finish(Path stage,Map<String,Object> state,List<String> warnings)throws IOException{state.put("finished_at",Instant.now().toString());status(stage,state);Files.writeString(stage.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\n"+String.join("\n\n",warnings)+"\n\nREQUIRED ACTION: "+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
    private static void manifest(Path stage)throws IOException{var files=new TreeMap<String,Object>();try(var walk=Files.walk(stage)){for(Path f:walk.filter(Files::isRegularFile).toList()){if(f.equals(stage.resolve("manifest.json")))continue;var p=NextflowFiles.pin(f,Long.MAX_VALUE,()->{});files.put(stage.relativize(f).toString().replace('\\','/'),Map.of("bytes",p.bytes(),"sha256",p.sha256()));}}Files.writeString(stage.resolve("manifest.json"),NextflowJson.json(Map.of("schema_version",1,"files",files))+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING);}
    private static void emit(PrintStream stream,String text){stream.println(text);stream.flush();}
}
